mapper.select:
select r.id as id, r.subsidy_person_id as subsidyPersonId, sp.name as personName, r.id_card_no as idCardNo, r.subsidy_type as subsidyType, r.suspension_id as suspensionId, r.recover_start_month as recoverStartMonth, r.recover_end_month as recoverEndMonth, r.recover_amount as recoverAmount, r.recovery_status as recoveryStatus, r.recovery_time as recoveryTime, r.create_time as createTime from shebao_finance_benefit_recovery r left join shebao_subsidy_person sp on sp.id = r.subsidy_person_id and sp.del_flag = '0' where r.del_flag = '0'
and sp.name like concat('%', #{req.personName}, '%')
and r.id_card_no like concat('%', #{req.idCardNo}, '%')
and r.subsidy_type = #{req.subsidyType}
and r.recovery_status = #{req.recoveryStatus}
order by r.recovery_status asc, r.create_time desc, r.id desc
